// src/stores/premium-store.ts
import { useStore } from 'zustand';
import { createStore } from 'zustand/vanilla';

import { ok } from '@/core/result';
import { DEFAULT_PREMIUM_STATE, premiumReducer } from '@/stores/premium-reducer';
import { useStores } from '@/stores/stores-context';

import type { Result } from '@/core/result';
import type { Entitlement, EntitlementFailure, EntitlementRepository } from '@/data/entitlements/entitlement-repository';
import type { PremiumState } from '@/stores/premium-reducer';
import type { StoreApi } from 'zustand/vanilla';

export type PremiumStoreState = PremiumState & {
  readonly grantPremium: (entitlement: Entitlement) => Result<void, EntitlementFailure>;
  readonly revokePremium: (revokedAtMs: number) => Result<void, EntitlementFailure>;
};

export type PremiumStore = StoreApi<PremiumStoreState>;

export type PremiumStoreDeps = { readonly entitlements: Pick<EntitlementRepository, 'current' | 'save'> };

/** The purchase service calls grantPremium; the store writes the entitlement, then shows it. */
export function createPremiumStore({ entitlements }: PremiumStoreDeps): PremiumStore {
  return createStore<PremiumStoreState>()((set, get) => ({
    ...premiumReducer(DEFAULT_PREMIUM_STATE, { type: 'replace-entitlement', entitlement: entitlements.current() }),
    grantPremium: (entitlement) => {
      const current = get();
      const next = premiumReducer(current, { type: 'grant-premium', entitlement });
      if (next === current) return ok(undefined);
      const saved = entitlements.save(entitlement);
      if (!saved.ok) return saved;
      set(next);
      return saved;
    },
    revokePremium: (revokedAtMs) => {
      const current = get();
      const next = premiumReducer(current, { type: 'revoke-premium', revokedAtMs });
      if (next === current || next.entitlement === null) return ok(undefined);
      const saved = entitlements.save(next.entitlement);
      if (!saved.ok) return saved;
      set(next);
      return saved;
    },
  }));
}

export function usePremiumStore<TSlice>(selector: (state: PremiumStoreState) => TSlice): TSlice {
  return useStore(useStores().premium, selector);
}

