import { useShallow } from 'zustand/shallow';

import { selectIsSignedIn } from '@/stores/auth/session-selectors';
import { useSessionStore } from '@/stores/auth/session-store-context';

export function useAccountBadge(): { readonly isSignedIn: boolean; readonly initials: string } {
  const isSignedIn = useSessionStore(selectIsSignedIn);
  const initials = useSessionStore((state) => state.initials);
  const flags = useSessionStore(useShallow((state) => [state.isSignedIn, state.isVerified]));
  return { isSignedIn: isSignedIn && flags[0] === true, initials };
}

