import { useState } from 'react';

import type { SessionRules, UndoableSession } from '@/stores/session/undoable-session-types';
import { createSessionStore, useUndoableSessionStore } from '@/stores/session/undoable-session-store';
import type { PersistSession } from '@/stores/session/undoable-session-store';

type Draft = { readonly done: readonly number[] };

export function useBulkEdit(
  rules: SessionRules<Draft, number>,
  initial: UndoableSession<Draft, number>,
  persist: PersistSession<Draft, number, never>,
): number {
  const [store] = useState(() => createSessionStore({ rules, initial, persist }));
  return useUndoableSessionStore(store, (state) => state.session.revision);
}
